using System;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents a pending operation against a partner instance.
/// </summary>
[Table("federation_jobs")]
public class FederationJob
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid JobId { get; set; }

  /// <summary>
  /// The id of the partner.
  /// </summary>
  public Guid PeerId { get; set; }
  public FederationPeer Peer { get; set; } = null!;

  /// <summary>
  /// The type of the operation.
  /// </summary>
  public int Type { get; set; }

  /// <summary>
  /// The id of the related local record if available.
  /// </summary>
  public Guid? RecordId { get; set; }

  /// <summary>
  /// The id of the related transaction if available.
  /// </summary>
  public Guid? TransactionId { get; set; }

  /// <summary>
  /// Number of failed attempts.
  /// </summary>
  public int Attempts { get; set; }

  /// <summary>
  /// Date when the operation is executed next.
  /// </summary>
  public DateTime NextAttemptAt { get; set; }

  /// <summary>
  /// The last error message if available.
  /// </summary>
  public string? LastError { get; set; }

  /// <summary>
  /// Indicates whether the operation failed finally. Failed operations are kept to show the problem and replaced by a new operation for the same record and partner.
  /// </summary>
  public bool Failed { get; set; }

  /// <summary>
  /// The size of the transferred file in bytes if the operation sends a file.
  /// </summary>
  public long? Size { get; set; }

  /// <summary>
  /// The number of bytes the partner received so far.
  /// </summary>
  public long Transferred { get; set; }

  /// <summary>
  /// Date when the operation was created.
  /// </summary>
  public DateTime CreatedAt { get; set; }

  /// <summary>
  /// The audit log entry, which shows the state of the operation, if available.
  /// </summary>
  public Guid? AuditEntryId { get; set; }
}
